"""Outbound shipping quotes and zone tables."""

from __future__ import annotations

from app import catalog, settings


class Address:
    def __init__(self, line: str, zone: str | None = None) -> None:
        self.line = line
        self.zone = zone or settings.default_zone()

    def normalized(self) -> str:
        return self.line.strip()

    def is_complete(self) -> bool:
        return bool(self.normalized())


_ZONE_RATES: dict[str, float] = {
    "domestic": 4.0,
    "express": 12.0,
    "intl": 18.0,
}


def zone_rate(zone: str) -> float:
    return float(_ZONE_RATES.get(zone, _ZONE_RATES["domestic"]))


def quote_zone(zone: str | None = None) -> str:
    return zone or settings.default_zone()


def base_postage(zone: str | None = None) -> float:
    return zone_rate(quote_zone(zone))


def weight_surcharge(weight_g: int) -> float:
    if weight_g <= 0:
        return 0.0
    extra = max(weight_g - 250, 0)
    return round(extra / 250.0 * 1.5, 2)


def quote_shipment(items: list[dict], zone: str | None = None) -> float:
    postage = base_postage(zone)
    postage += weight_surcharge(catalog.line_weight(items))
    return round(postage, 2)


def can_ship(items: list[dict]) -> bool:
    return not catalog.digital_only(items)


def destination_ok(address: Address) -> bool:
    return address.is_complete()


def format_label(address: Address, items: list[dict]) -> str:
    titles = ", ".join(catalog.describe_items(items))
    return f"{address.normalized()} / {quote_zone(address.zone)} / {titles}"


def estimate_days(zone: str | None = None) -> int:
    chosen = quote_zone(zone)
    if chosen == "express":
        return 1
    if chosen == "intl":
        return 7
    return 3


def reset_store() -> None:
    _ZONE_RATES["domestic"] = 4.0
    _ZONE_RATES["express"] = 12.0
    _ZONE_RATES["intl"] = 18.0

"""Pick, pack, and dispatch helpers for physical lines."""

from __future__ import annotations

from app import catalog, shipping


class PickJob:
    def __init__(self, order_id: int, sku: str, qty: int) -> None:
        self.order_id = order_id
        self.sku = sku
        self.qty = qty
        self.packed = False

    def mark_packed(self) -> None:
        self.packed = True

    def as_dict(self) -> dict:
        return {
            "order_id": self.order_id,
            "sku": self.sku,
            "qty": self.qty,
            "packed": self.packed,
        }


_JOBS: list[PickJob] = []


def plan_picks(order_id: int, items: list[dict]) -> list[dict]:
    jobs: list[dict] = []
    for item in items:
        sku = str(item.get("sku") or "widget")
        if not catalog.is_shippable(sku):
            continue
        job = PickJob(order_id, sku, int(item.get("qty", 1) or 1))
        _JOBS.append(job)
        jobs.append(job.as_dict())
    return jobs


def pack_next() -> dict | None:
    for job in _JOBS:
        if not job.packed:
            job.mark_packed()
            return job.as_dict()
    return None


def pending_count() -> int:
    return sum(1 for job in _JOBS if not job.packed)


def postage_for(items: list[dict]) -> float:
    return shipping.quote_shipment(items)


def jobs_for(order_id: int) -> list[dict]:
    return [job.as_dict() for job in _JOBS if job.order_id == order_id]


def reset_store() -> None:
    _JOBS.clear()

"""SKU metadata and merchandising helpers."""

from __future__ import annotations


class CatalogEntry:
    def __init__(self, sku: str, title: str, shippable: bool, weight_g: int) -> None:
        self.sku = sku
        self.title = title
        self.shippable = shippable
        self.weight_g = weight_g

    def label(self) -> str:
        return f"{self.title} ({self.sku})"

    def is_physical(self) -> bool:
        return self.shippable and self.weight_g > 0


_ENTRIES: dict[str, CatalogEntry] = {
    "widget": CatalogEntry("widget", "Standard widget", True, 250),
    "gadget": CatalogEntry("gadget", "Standard gadget", True, 400),
    "ebook": CatalogEntry("ebook", "Download title", False, 0),
}


def get_entry(sku: str) -> CatalogEntry:
    return _ENTRIES.get(sku) or CatalogEntry(sku, sku, True, 100)


def title_for(sku: str) -> str:
    return get_entry(sku).title


def is_shippable(sku: str) -> bool:
    return get_entry(sku).is_physical()


def weight_grams(sku: str) -> int:
    return int(get_entry(sku).weight_g)


def register_entry(sku: str, title: str, shippable: bool = True, weight_g: int = 100) -> CatalogEntry:
    entry = CatalogEntry(sku, title, shippable, weight_g)
    _ENTRIES[sku] = entry
    return entry


def known_skus() -> list[str]:
    return sorted(_ENTRIES)


def line_weight(items: list[dict]) -> int:
    total = 0
    for item in items:
        sku = str(item.get("sku") or "widget")
        qty = int(item.get("qty", 1) or 1)
        total += weight_grams(sku) * max(qty, 0)
    return total


def describe_items(items: list[dict]) -> list[str]:
    return [title_for(str(item.get("sku") or "widget")) for item in items]


def digital_only(items: list[dict]) -> bool:
    return False


def reset_store() -> None:
    _ENTRIES.clear()
    _ENTRIES["widget"] = CatalogEntry("widget", "Standard widget", True, 250)
    _ENTRIES["gadget"] = CatalogEntry("gadget", "Standard gadget", True, 400)
    _ENTRIES["ebook"] = CatalogEntry("ebook", "Download title", False, 0)

"""Quotes, tax, and coupons.

A coupon code should change the payable amount at most once. Checkout currently
does not call ``compute_checkout_total``.
"""

COUPONS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
}


def quote_price(sku: str, qty: int, unit_price: float) -> float:
    """Unit quote helper; not used by ``orders.create_order``."""
    return round(unit_price * qty, 2)


def apply_tax(subtotal: float, tax_rate: float = 0.0) -> float:
    return round(subtotal * (1 + tax_rate), 2)


def apply_coupon(amount: float, code: str | None) -> float:
    if not code:
        return round(float(amount), 2)
    rate = COUPONS.get(code.upper(), 0.0)
    return round(float(amount) * (1.0 - rate), 2)


def compute_checkout_total(
    items: list[dict],
    coupon: str | None = None,
    tax_rate: float = 0.0,
) -> float:
    """One-shot subtotal → coupon → tax. Unused by the order service today."""
    subtotal = sum(float(item["price"]) * int(item.get("qty", 1)) for item in items)
    discounted = apply_coupon(subtotal, coupon)
    return apply_tax(discounted, tax_rate)

